#!/usr/bin/env bash
# Copy the browser build into apps/site/public/verify/ (the hosted page at /verify/) and write
# MANIFEST.sha256 there. The site build has no Rust toolchain, so the generated files are
# committed; the manifest is what makes a stale or hand-edited copy detectable.
#   publish-site.sh           rebuild with build.sh, then overwrite the committed copy
#   publish-site.sh --check   rebuild with build.sh, then fail if the committed copy differs
# --check needs the same rustc and wasm-bindgen-cli versions as the build that wrote the copy.
set -euo pipefail
cd "$(dirname "$0")"
mode="${1:-publish}"
case "$mode" in publish | --check) ;; *) echo "usage: $0 [--check]" >&2; exit 2 ;; esac
dest="../../apps/site/public/verify"
./build.sh
stage="$(mktemp -d)"
trap 'rm -rf "$stage"' EXIT
mkdir -p "$stage/pkg"
cp web/pkg/tracelane_verifier_wasm.js web/pkg/wasm-bytes.js "$stage/pkg/"
cp web/verify.js "$stage/verify.js"
# verify.css is hand-written, not built: the manifest pins its hash and --check requires it to be
# listed, and rejects any other file in the directory.
files=(MANIFEST.sha256 verify.css verify.js samples.js pkg/tracelane_verifier_wasm.js pkg/wasm-bytes.js)
if [ -f "$dest/verify.css" ]; then cp "$dest/verify.css" "$stage/verify.css"
elif [ "$mode" = publish ]; then echo "missing $dest/verify.css (hand-written; add it before publishing)" >&2; exit 1
fi
# Sample bundles as base64 modules, like wasm-bytes.js: the page never fetches them.
node -e '
const fs = require("fs");
const b64 = (f) => fs.readFileSync(`fixtures/${f}`).toString("base64");
fs.writeFileSync(process.argv[1],
  `// Generated by publish-site.sh from fixtures/. Synthetic sample data, not real evidence.\n` +
  `export const good = "${b64("good.zip")}";\n` +
  `export const tampered = "${b64("tampered.zip")}";\n` +
  `export const publicKey = "${fs.readFileSync("fixtures/workspace.pub", "utf8").trim()}";\n`);
' "$stage/samples.js"
{
  head -1 "$stage/pkg/wasm-bytes.js" | sed 's|^// Generated by build.sh\. |# wasm: |'
  (cd "$stage" && sha256sum $([ -f verify.css ] && echo verify.css) verify.js samples.js pkg/tracelane_verifier_wasm.js pkg/wasm-bytes.js)
} > "$stage/MANIFEST.sha256"
if [ "$mode" = "--check" ]; then
  # No hosted copy committed (the page lands in its own change): nothing to compare, the build above
  # still ran. Once apps/site/public/verify/ exists, every file below must match.
  if [ ! -d "$dest" ]; then echo "no hosted copy at $dest; build succeeded, nothing to compare"; exit 0; fi
  # Exactly the listed files, all regular (see check-site-listing.sh); then each must equal a fresh build.
  bash ./check-site-listing.sh "$dest" "${files[@]}" || exit 1
  for f in "${files[@]}"; do
    [ -f "$stage/$f" ] || { echo "MISSING from the fresh build: $f" >&2; exit 1; }
    cmp -s "$stage/$f" "$dest/$f" || { echo "DRIFT: $dest/$f differs from a fresh build" >&2; exit 1; }
  done
  echo "site copy matches a fresh build"
else
  mkdir -p "$dest/pkg"
  for f in "${files[@]}"; do [ "$f" = verify.css ] || cp "$stage/$f" "$dest/$f"; done
  cat "$dest/MANIFEST.sha256"
fi
